-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE failure_modes SET remediation = replace(remediation, ' | ASK-GROUND-3 (qnfo-ai-search 2.5.0, 2026-10-13): the stored judge context was still cut at 12000 characters while the writer read more; it is now stored whole (48000 cap) and judged hourly', '') WHERE fm_key = 'judge-context-narrower-than-writer'
-- ASK-GROUND-3 + ASK-CRAWLER-GATE-1 (2026-10-13, qnfo-ai-search 2.5.0 in the same pull request, agent_issues 2165 and 2339,
-- pillar reach). Closing probes for both issues (UPDATE of their birth contracts, ORPHAN-GUARD-BIRTH-1) and the failure-mode
-- note: the judge-context failure mode was still live on main (logEvent cut the stored judge context at 12000 characters;
-- 7 of 13 full-context rows were cut), so its remediation text records the second fix.
UPDATE remediation_contracts SET verify_transport = 'd1-query', verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT MIN(ts) FROM ask_loop_runs WHERE kind = ''measure'' AND (version GLOB ''2.[5-9].*'' OR version GLOB ''2.[1-9][0-9].*'' OR version GLOB ''[3-9].*'')) IS NULL THEN ''pending: qnfo-ai-search 2.5.0 (ASK-GROUND-3) has not run a measure tick'' WHEN (SELECT last_refreshed FROM metric_registry WHERE metric = ''ask_grounded_share_7d'') < strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-3 hours'') THEN ''pending: ask_grounded_share_7d not refreshed in 3 h (stale value '' || (SELECT last_value FROM metric_registry WHERE metric = ''ask_grounded_share_7d'') || '')'' WHEN (SELECT COALESCE(SUM(judged_total), 0) FROM ask_events WHERE judge = 2 AND judged_total IS NOT NULL AND cached = 0 AND (limited IS NULL OR limited = ''client-gone'') AND ts >= (SELECT MIN(ts) FROM ask_loop_runs WHERE kind = ''measure'' AND (version GLOB ''2.[5-9].*'' OR version GLOB ''2.[1-9][0-9].*'' OR version GLOB ''[3-9].*''))) < 20 THEN ''pending: fewer than 20 judged claims on answers written by 2.5.0 or later'' WHEN (SELECT 1.0 * SUM(judged_supported) / SUM(judged_total) FROM ask_events WHERE judge = 2 AND judged_total IS NOT NULL AND cached = 0 AND (limited IS NULL OR limited = ''client-gone'') AND ts >= (SELECT MIN(ts) FROM ask_loop_runs WHERE kind = ''measure'' AND (version GLOB ''2.[5-9].*'' OR version GLOB ''2.[1-9][0-9].*'' OR version GLOB ''[3-9].*''))) < 0.7 THEN ''grounded share on answers written by 2.5.0 or later is under 0.7'' WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''ask_grounded_share_7d'') AS REAL) >= 0.7 THEN ''ok'' ELSE ''ask_grounded_share_7d = '' || (SELECT last_value FROM metric_registry WHERE metric = ''ask_grounded_share_7d'') || '' (kill band < 0.7)'' END AS observed', status = 'active', attempts = 0, last_verdict = NULL, next_due_at = datetime('now') WHERE class = 'issue-2165';
UPDATE remediation_contracts SET verify_transport = 'd1-query', verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT MIN(ts) FROM ask_loop_runs WHERE version GLOB ''2.[5-9].*'' OR version GLOB ''2.[1-9][0-9].*'' OR version GLOB ''[3-9].*'') IS NULL THEN ''pending: qnfo-ai-search 2.5.0 (ASK-CRAWLER-GATE-1) has not run'' WHEN (SELECT MIN(ts) FROM ask_loop_runs WHERE version GLOB ''2.[5-9].*'' OR version GLOB ''2.[1-9][0-9].*'' OR version GLOB ''[3-9].*'') > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-24 hours'') THEN ''pending: under 24 hours since qnfo-ai-search 2.5.0 first ran'' WHEN 2 * (SELECT COUNT(*) FROM ask_events WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-24 hours'') AND query NOT LIKE ''[paper:%'' AND limited = ''client-gone'') < (SELECT COUNT(*) FROM ask_events WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-24 hours'') AND query NOT LIKE ''[paper:%'') OR (SELECT COUNT(*) FROM ask_events WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-24 hours'') AND limited = ''client-gone'') = 0 THEN ''ok'' ELSE ''pending: '' || (SELECT COUNT(*) FROM ask_events WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-24 hours'') AND query NOT LIKE ''[paper:%'' AND limited = ''client-gone'') || '' of '' || (SELECT COUNT(*) FROM ask_events WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-24 hours'') AND query NOT LIKE ''[paper:%'') || '' unpinned ask events in 24 h ended client-gone (target under half)'' END AS observed', status = 'active', attempts = 0, last_verdict = NULL, next_due_at = datetime('now') WHERE class = 'issue-2339';
UPDATE failure_modes SET remediation = remediation || ' | ASK-GROUND-3 (qnfo-ai-search 2.5.0, 2026-10-13): the stored judge context was still cut at 12000 characters while the writer read more; it is now stored whole (48000 cap) and judged hourly' WHERE fm_key = 'judge-context-narrower-than-writer';
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested) VALUES
  ('session_01Kddqwk5gQT5qSSHVKjT2EA', 'grounding of an answer does not depend on whether the reader stayed, and an answer must say nothing its excerpts do not say',
   'ASK-GROUND-3 + ASK-CRAWLER-GATE-1 (qnfo-ai-search 2.5.0): the grounded share counts every fully written full-context answer; the judge stores the whole context and runs hourly; a quoted paper title brings that paper in as source 1; the writer may not infer what no excerpt states; a deterministic pass removes speculation sentences; deep links ask only after a real user event and declared crawlers get 403 with no model call',
   'ask_events 7 days: 141 events, 121 client-gone (112 the paper-page deep link, Chrome user agents from CN, SG and HK every 15-30 minutes); 45 full-context claims, 37 supported (0.822) but the metric stopped refreshing at 0.561 because only 9 claims had limited NULL; 7 of 13 stored judge contexts cut at 12000 characters; 6 of 8 unsupported claims answer the falsification question from nothing',
   'merged through the canonical path', 'qnfo-ai-search answers and its metrics', 'revert qnfo-ai-search to 2.4.2 through the canonical path',
   'ask.qwav.tech answers only from its sources and its quality metric measures every answer',
   'ask_grounded_share_7d reads at least 0.7 at the first hourly measure after the deploy and stays above it on post-deploy answers; client-gone falls under half of unpinned questions within 24 h', 'ask.qwav.tech readers', 'd1:ask_events, cloudflare request analytics');
